```go
func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
    r.mu.Lock()
    defer r.mu.Unlock()

    id := strings.TrimSpace(adjustmentID)
    if id == "" {
        return nil, fail(ErrInvalidID, "", "调整编号为空")
    }

    // 幂等：编号已成功使用
    if prev, ok := r.adjustments[id]; ok {
        if r.contents[id] == canonicalKey(ops) {
            return cloneResult(prev), nil
        }
        return nil, fail(ErrAdjustmentIDConflict, id, "调整编号 %s 已用于不同内容", id)
    }

    if len(ops) == 0 {
        return nil, fail(ErrEmptyAdjustment, id, "调整 %s 为空", id)
    }

    // 校验操作
    seen := make(map[string]bool)
    type validatedOp struct {
        op Op
        c *cargo
        target *compartment
    }
    vops := make([]validatedOp, 0, len(ops))
    for _, op := range ops {
        cargoID := strings.TrimSpace(op.CargoID)
        if cargoID == "" {
            return nil, fail(ErrInvalidID, "", "货物编号为空")
        }
        c, ok := r.cargos[cargoID]
        if !ok {
            return nil, fail(ErrNotFound, cargoID, "货物 %s 不存在", cargoID)
        }
        if seen[cargoID] {
            return nil, fail(ErrDuplicateOp, cargoID, "货物 %s 在调整中出现多次", cargoID)
        }
        seen[cargoID] = true

        switch op.Kind {
        case OpLoad:
            if c.compartmentID != "" {
                return nil, fail(ErrStateMismatch, cargoID, "货物 %s 已装载于舱位 %s，不能重复装载", cargoID, c.compartmentID)
            }
            targetID := strings.TrimSpace(op.Target)
            if targetID == "" {
                return nil, fail(ErrInvalidID, "", "目标舱位编号为空")
            }
            t, ok := r.compartments[targetID]
            if !ok {
                return nil, fail(ErrNotFound, targetID, "舱位 %s 不存在", targetID)
            }
            vops = append(vops, validatedOp{op, c, t})
        case OpUnload:
            if c.compartmentID == "" {
                return nil, fail(ErrStateMismatch, cargoID, "货物 %s 未装载，不能卸下", cargoID)
            }
            vops = append(vops, validatedOp{op, c, nil})
        case OpMove:
            if c.compartmentID == "" {
                return nil, fail(ErrStateMismatch, cargoID, "货物 %s 未装载，不能移动", cargoID)
            }
            targetID := strings.TrimSpace(op.Target)
            if targetID == "" {
                return nil, fail(ErrInvalidID, "", "目标舱位编号为空")
            }
            t, ok := r.compartments[targetID]
            if !ok {
                return nil, fail(ErrNotFound, targetID, "舱位 %s 不存在", targetID)
            }
            if t.id == c.compartmentID {
                return nil, fail(ErrDuplicateOp, cargoID, "货物 %s 已在舱位 %s，不能移动到原舱位", cargoID, t.id)
            }
            vops = append(vops, validatedOp{op, c, t})
        default:
            return nil, fail(..., cargoID, "未知操作种类")
        }
    }
```

Wait — move to same compartment: is that "重复操作"? The spec says "移动到原舱位也应拒绝". Reason categories: 不存在、状态不符、重复操作、超重、混装冲突. Move-to-same could be 重复操作 (duplicate/no-op). I'll use ErrDuplicateOp.

Now simulate final state. Build final compartment cargo sets:

```go
    // 模拟最终配载
    final := make(map[string]map[string]*cargo, len(r.compartments))
    for id, comp := range r.compartments {
        m := make(map[string]*cargo, len(comp.cargo))
        for cid, c := range comp.cargo {
            m[cid] = c
        }
        final[id] = m
    }
    // 应用操作（在模拟上）
    for _, v := range vops {
        c := v.c
        switch v.op.Kind {
        case OpLoad:
            final[v.target.id][c.id] = c
        case OpUnload:
            delete(final[c.compartmentID], c.id)
        case OpMove:
            delete(final[c.compartmentID], c.id)
            final[v.target.id][c.id] = c
        }
    }
```

Then check each compartment:

```go
    for id, set := range final {
        var sum int64
        destinations := make(map[string]bool)
        for _, c := range set {
            if c.weight > math.MaxInt64 - sum {
                return nil, fail(ErrOverflow, id, "舱位 %s 重量超过可表示范围", id)
            }
            sum += c.weight
            destinations[c.destination] = true
        }
        comp := r.compartments[id]
        if sum > comp.maxWeight {
            return nil, fail(ErrOverweight, id, "舱位 %s 总重量 %d 超过承重 %d", id, sum, comp.maxWeight)
        }
        if len(destinations) > 1 {
            for _, c := range set {
                if !c.allowMixed {
                    return nil, fail(ErrMixedLoading, c.id, "舱位 %s 混装冲突：货物 %s 不允许与不同目的地货物混装", id, c.id)
                }
            }
        }
    }
```

Wait, mixed loading check: "不同目的地共舱时所有货物都必须允许混装". If destinations differ and any cargo doesn't allow mixed → conflict. The error should point to the cargo that doesn't allow mixed (involved cargo). Also possibly mention the compartment. Good.

Also overflow: weights are positive int64, each ≤ MaxInt64. Sum overflow check `c.weight > MaxInt64 - sum` — since sum ≥ 0, MaxInt64 - sum is safe. Good.

Then apply for real:

