    // 全部合法，正式生效
    cargoChanges := make([]CargoChange, 0, len(vops))
    compWeights := make(map[string][2]int64) // id -> [before, after]
    affectedComps := make(map[string]bool)
    for _, v := range vops {
        c := v.c
        from := c.compartmentID
        var to string
        switch v.op.Kind {
        case OpLoad:
            r.compartments[v.target.id].cargo[c.id] = c
            c.compartmentID = v.target.id
            to = v.target.id
        case OpUnload:
