func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
    r.mu.Lock(); defer r.mu.Unlock()
    cid := strings.TrimSpace(id)
    if cid == "" { return fail(ErrInvalidID, "", "舱位编号为空") }
    if maxWeight <= 0 { return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数", cid) }
    if _, ok := r.compartments[cid]; ok {
