package stowage

import (
	"encoding/json"
	"math"
	"sort"
	"strings"
)

// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
//
// 调整编号遵循编号规则（去空白后非空）。成功后以相同编号和相同内容
// 重复提交，返回首次成功的结果而不再改变配载；同一编号用于不同内容
// 被拒绝。失败的调整不占用编号。
//
// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
// 都不生效。合法性按全部操作完成后的最终配载判断。
func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	aid := strings.TrimSpace(adjustmentID)
	if aid == "" {
		return nil, fail(ErrInvalidID, "", "调整编号为空")
	}

	// 幂等：编号已成功使用过。
	if saved, ok := r.adjustments[aid]; ok {
		if r.contents[aid] == canonicalKey(ops) {
			return cloneResult(saved), nil
		}
		return nil, fail(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
	}

	if len(ops) == 0 {
		return nil, fail(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
	}

	// 逐条校验操作。
	seen := make(map[string]bool)
	type validOp struct {
		op     Op
		cargo  *cargo
		target *compartment // 装载/移动的目标舱位；卸下时为 nil
	}
	vops := make([]validOp, 0, len(ops))
	affected := make(map[string]bool)

	for _, op := range ops {
		cid := strings.TrimSpace(op.CargoID)
		if cid == "" {
			return nil, fail(ErrInvalidID, "", "货物编号为空")
		}
		c, ok := r.cargos[cid]
		if !ok {
			return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
		}
		if seen[cid] {
			return nil, fail(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
		}
		seen[cid] = true

		switch op.Kind {
		case OpLoad:
			if c.compartmentID != "" {
				return nil, fail(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
			}
			tid := strings.TrimSpace(op.Target)
			if tid == "" {
				return nil, fail(ErrInvalidID, "", "目标舱位编号为空")
			}
			t, ok := r.compartments[tid]
			if !ok {
				return nil, fail(ErrNotFound, tid, "舱位 %s 不存在", tid)
			}
			vops = append(vops, validOp{op, c, t})
			affected[t.id] = true
		case OpUnload:
			if c.compartmentID == "" {
				return nil, fail(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
			}
			vops = append(vops, validOp{op, c, nil})
			affected[c.compartmentID] = true
		case OpMove:
			if c.compartmentID == "" {
				return nil, fail(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
			}
			tid := strings.TrimSpace(op.Target)
			if tid == "" {
				return nil, fail(ErrInvalidID, "", "目标舱位编号为空")
			}
			t, ok := r.compartments[tid]
			if !ok {
				return nil, fail(ErrNotFound, tid, "舱位 %s 不存在", tid)
			}
			if t.id == c.compartmentID {
				return nil, fail(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
			}
			vops = append(vops, validOp{op, c, t})
			affected[c.compartmentID] = true
			affected[t.id] = true
		default:
			return nil, fail(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
		}
	}

	// 在模拟配载上应用全部操作。
	final := make(map[string]map[string]*cargo, len(r.compartments))
	for id, comp := range r.compartments {
		set := make(map[string]*cargo, len(comp.cargo))
		for cid, c := range comp.cargo {
			set[cid] = c
		}
		final[id] = set
	}
	for _, v := range vops {
		switch v.op.Kind {
		case OpLoad:
			final[v.target.id][v.cargo.id] = v.cargo
		case OpUnload:
			delete(final[v.cargo.compartmentID], v.cargo.id)
		case OpMove:
			delete(final[v.cargo.compartmentID], v.cargo.id)
			final[v.target.id][v.cargo.id] = v.cargo
		}
	}

	// 按最终配载校验承重与混装限制。
	for id, set := range final {
		var sum int64
		destinations := make(map[string]bool)
		for _, c := range set {
			if c.weight > math.MaxInt64-sum {
				return nil, fail(ErrOverflow, id, "舱位 %s 重量合计超过 int64 可表示范围", id)
			}
			sum += c.weight
			destinations[c.destination] = true
		}
		if sum > r.compartments[id].maxWeight {
			return nil, fail(ErrOverweight, id, "舱位 %s 总重量 %d 千克超过最大承重 %d 千克", id, sum, r.compartments[id].maxWeight)
		}
		if len(destinations) > 1 {
			for _, c := range set {
				if !c.allowMixed {
					return nil, fail(ErrMixedLoading, c.id, "舱位 %s 存在不同目的地货物，但货物 %s 不允许混装", id, c.id)
				}
			}
		}
	}

	// 全部合法，正式生效。
	cargoChanges := make([]CargoChange, 0, len(vops))
	compChanges := make([]CompartmentChange, 0, len(affected))
	for id := range affected {
		before := sumSet(r.compartments[id].cargo)
		after := sumSet(final[id])
		compChanges = append(compChanges, CompartmentChange{
			CompartmentID: id,
			WeightBefore:  before,
			WeightAfter:   after,
		})
	}
	sort.Slice(compChanges, func(i, j int) bool {
		return compChanges[i].CompartmentID < compChanges[j].CompartmentID
	})

	for _, v := range vops {
		c := v.cargo
		from := c.compartmentID
		var to string
		switch v.op.Kind {
		case OpLoad:
			r.compartments[v.target.id].cargo[c.id] = c
			c.compartmentID = v.target.id
			to = v.target.id
		case OpUnload:
			delete(r.compartments[from].cargo, c.id)
			c.compartmentID = ""
		case OpMove:
			delete(r.compartments[from].cargo, c.id)
			r.compartments[v.target.id].cargo[c.id] = c
			c.compartmentID = v.target.id
			to = v.target.id
		}
		cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	result := &AdjustmentResult{ID: aid, CargoChanges: cargoChanges, CompartmentChanges: compChanges}
	r.adjustments[aid] = result
	r.contents[aid] = canonicalKey(ops)
	return cloneResult(result), nil
}
