	se := requireError(t, func() error {
		_, err := r.Adjust("A2", []Op{
			{Kind: OpMove, CargoID: "G1", Target: "C2"},
			{Kind: OpUnload, CargoID: "G1"},
		})
		return err
	}(), ErrDuplicateOp)
